#!/usr/bin/env bash
set -e

BUILD="522026 Alpha"
INSTALL_DIR="/root/mythos"

cat <<'EULA_TEXT'
# Mythos End User License Agreement

Build: 522026 Alpha

By installing or using Mythos, you agree to the terms below.

## 1. Purpose

Mythos is a simple VPS program runner. It is designed to help you start, stop, restart, and monitor programs that you choose to install on your own server.

## 2. User responsibility

You are responsible for every program you run through Mythos.

Do not use Mythos to run malware, spam tools, credential stealers, botnets, abusive automation, illegal services, or anything that violates your hosting provider's rules.

## 3. No included programs

Mythos does not include Discord bots, game servers, web apps, databases, or paid software. It only provides a basic way to run commands and manage programs you add yourself.

## 4. Server access

Mythos can start and stop commands on your VPS. Only install it on servers you own or are allowed to manage.

## 5. No warranty

Mythos is provided as-is. It may contain bugs. You should back up important files before installing, updating, or changing server software.

## 6. Installer acceptance

The Mythos self-extracting installer requires you to type ACCEPT before it extracts the Mythos files.

Mythos also stores local EULA acceptance after installation so the program manager can run normally.

EULA_TEXT

echo ""
echo "To install Mythos $BUILD, type ACCEPT and press Enter."
echo "Anything else will cancel installation."
read -r ANSWER

if [ "$ANSWER" != "ACCEPT" ]; then
  echo "EULA not accepted. Mythos was not extracted or installed."
  exit 1
fi

echo ""
echo "EULA accepted. Extracting Mythos $BUILD..."

if ! command -v unzip >/dev/null 2>&1; then
  echo "unzip not found. Installing unzip first..."
  apt update
  apt install -y unzip
fi

TMP_ZIP="/tmp/mythos_522026_alpha_payload.zip"
cat > "$TMP_ZIP.b64" <<'PAYLOAD_B64'

PAYLOAD_B64

base64 -d "$TMP_ZIP.b64" > "$TMP_ZIP"
rm -f "$TMP_ZIP.b64"

cd /root
rm -rf "$INSTALL_DIR"
unzip -q "$TMP_ZIP"
rm -f "$TMP_ZIP"

# Payload extracts as mythos-522026-alpha for GitHub naming.
# Move it to /root/mythos for runtime simplicity.
if [ -d /root/mythos-522026-alpha ]; then
  mv /root/mythos-522026-alpha "$INSTALL_DIR"
fi

mkdir -p "$INSTALL_DIR/.mythos"
touch "$INSTALL_DIR/.mythos/installer_eula_accepted"

cd "$INSTALL_DIR"
chmod +x install.sh mythos.py examples/test_program.py
./install.sh

echo ""
echo "Mythos $BUILD installed at $INSTALL_DIR."
